import{_ as e,o as i,c as s,a2 as o}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Alquimia","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/professions/alchemy.md","filePath":"es/guide/professions/alchemy.md"}'),r={name:"es/guide/professions/alchemy.md"};function t(n,a,l,c,d,p){return i(),s("div",null,[...a[0]||(a[0]=[o('<h1 id="alchemy" tabindex="-1">Alquimia <a class="header-anchor" href="#alchemy" aria-label="Enlace permanente a &quot;Alquimia&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · No establecido como jugable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Explora reacciones entre materiales para crear preparados útiles.</li><li>La habilidad, las técnicas aprendidas y la ejecución importan junto con la fórmula.</li><li>Las mezclas médicas, el humo, las toxinas y los materiales dan a los alquimistas funciones en expediciones y comercio.</li></ul><p><span id="at-a-glance"></span><span id="what-it-does"></span><span id="why-take-it-into-the-field"></span><span id="learning-and-specialization"></span><span id="progression-and-related-crafts"></span><span id="magic-materials"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Actividad</th><th>Qué haces</th></tr></thead><tbody><tr><td>Preparar</td><td>Tritura, disuelve, calienta, destila, separa y combina.</td></tr><tr><td>Observar</td><td>Registra reacciones en un diario alquímico; convierte observaciones en formulaciones comprendidas.</td></tr><tr><td>Usar o comerciar</td><td>Crea aceites, ungüentos, polvos, tintas, disolventes, reactivos y mezclas volátiles.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Dirección de Syrolands</th></tr></thead><tbody><tr><td>Los reactivos y un menú de fabricación producen pociones conocidas.</td><td>Los procesos y las reacciones que descubres dan forma a las formulaciones.</td></tr><tr><td>Las pociones de curación, antídoto, veneno y explosión ya tienen utilidad de campo.</td><td>Preparados más variados podrían conectar medicina, humo, adhesivos y otros oficios.</td></tr></tbody></table><p>La comparación usa los ciclos conocidos de los oficios de UO; las referencias oficiales también cubren expansiones posteriores. <a href="https://uo.com/wiki/ultima-online-wiki/skills/alchemy/" target="_blank" rel="noreferrer">Alchemy</a>.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un analgésico podría reducir temporalmente las penalizaciones por dolor sin reparar el trauma que las causa. Sus efectos médicos y sus contramedidas siguen sin decidirse.</p><h2 id="progression-and-trade-offs" tabindex="-1">Progresión y compromisos <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Enlace permanente a &quot;Progresión y compromisos&quot;">​</a></h2><ul><li>Destilación y Toxicología son posibles caminos de aprendizaje. La pureza, la estabilidad y la calidad del material afectan al resultado.</li><li>Copiar una receta no copia el dominio de quien la creó. Las recetas de reactivos siguen sin decidirse y los materiales transportados pueden saquearse.</li></ul><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/professions/tinkering.html">Mecánica</a> · <a href="/Syrolands-Public/es/guide/professions/tailoring.html">Sastrería</a> · <a href="/Syrolands-Public/es/guide/magic/spellbooks-scrolls-and-reagents.html">Materiales mágicos</a> · <a href="/Syrolands-Public/es/guide/professions/overview.html">Sistema de profesiones</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/professions/alchemy.html">Alquimia</a></p>',18)])])}const h=e(r,[["render",t]]);export{u as __pageData,h as default};
